CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'en' CHECK(language IN ('en','vi')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_natal_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER natal_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_natal_profile();
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','user')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(user_id uuid, role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=$1 AND r.role=$2) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated;
CREATE TABLE public.perfumes (id text PRIMARY KEY, name text NOT NULL, brand text NOT NULL DEFAULT '', price numeric NOT NULL CHECK(price>0), currency text NOT NULL DEFAULT 'USD', size_ml numeric NOT NULL CHECK(size_ml>0), style text NOT NULL CHECK(style IN ('feminine','masculine','unisex')), scent_family text NOT NULL, top_notes text[] NOT NULL DEFAULT '{}', heart_notes text[] NOT NULL DEFAULT '{}', base_notes text[] NOT NULL DEFAULT '{}', intensity integer NOT NULL CHECK(intensity BETWEEN 1 AND 5), mood_tags text[] NOT NULL DEFAULT '{}', image_url text, sold_out boolean NOT NULL DEFAULT false, sample_price numeric CHECK(sample_price>0), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.perfumes TO anon,authenticated; GRANT ALL ON public.perfumes TO service_role; GRANT INSERT,UPDATE,DELETE ON public.perfumes TO authenticated;
ALTER TABLE public.perfumes ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalogue ON public.perfumes FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_catalogue ON public.perfumes FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.no_private_birth_fields(payload jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT NOT jsonb_path_exists(payload, '$.**.keyvalue() ? (@.key == "lat" || @.key == "lon" || @.key == "latitude" || @.key == "longitude" || @.key == "timezone" || @.key == "city" || @.key == "country" || @.key == "place" || @.key == "day" || @.key == "month" || @.key == "year" || @.key == "hour" || @.key == "minute" || @.key == "birthDate" || @.key == "birthTime" || @.key == "birthPlace")') $$;
CREATE TABLE public.saved_charts (id text PRIMARY KEY, user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, nickname text NOT NULL DEFAULT '', chart jsonb NOT NULL CHECK(public.no_private_birth_fields(chart)), prefs jsonb NOT NULL DEFAULT '{}' CHECK(public.no_private_birth_fields(prefs)), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_charts TO authenticated; GRANT ALL ON public.saved_charts TO service_role;
ALTER TABLE public.saved_charts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_charts ON public.saved_charts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.saved_rituals (user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, ritual_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,ritual_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_rituals TO authenticated; GRANT ALL ON public.saved_rituals TO service_role;
ALTER TABLE public.saved_rituals ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_rituals ON public.saved_rituals FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('reading','today','ask','match')), ref text NOT NULL, rating integer NOT NULL CHECK(rating IN (-1,1)), lang text NOT NULL CHECK(lang IN ('en','vi')), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.feedback TO anon,authenticated; GRANT SELECT,DELETE ON public.feedback TO authenticated; GRANT ALL ON public.feedback TO service_role;
ALTER TABLE public.feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_feedback ON public.feedback FOR INSERT TO anon,authenticated WITH CHECK(user_id IS NOT DISTINCT FROM auth.uid());
CREATE POLICY admin_feedback ON public.feedback FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.delete_my_natal_data() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; DELETE FROM public.saved_charts WHERE user_id=auth.uid(); DELETE FROM public.saved_rituals WHERE user_id=auth.uid(); DELETE FROM public.feedback WHERE user_id=auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.delete_my_natal_data() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.delete_my_natal_data() TO authenticated;
CREATE TABLE public.app_settings (key text PRIMARY KEY, value jsonb NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.app_settings TO authenticated; GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_settings ON public.app_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));